/* ---------- captions (burned in, word for word; max 2 lines, bottom edge at y=1350) ---------- */

// [scene, firstWord, lastWord] per caption chunk; chunks cover every narrated word once, in order.
export const CHUNKS: [number, number, number][] = [
  [0, 0, 4],
  [1, 0, 3],
  [1, 4, 9],
  [2, 0, 3],
  [2, 4, 10],
  [3, 0, 5],
  [4, 0, 4],
  [4, 5, 7],
  [5, 0, 5],
];
const TOKENS = LINES.map((s) => s.text.split(' '));

const Captions: React.FC = () => {
  const f = useCurrentFrame();
  let idx = -1;
  CHUNKS.forEach(([s, a], i) => {
    if (f >= wordF(s, a) - 1) idx = i;
  });
  if (idx < 0) return null;
  const [s, a, b] = CHUNKS[idx];
  const first = wordF(s, a);
  const t = interpolate(f, [first - 1, first + 3], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  return (
    <Layer kind="cap">
      <div style={{position: 'absolute', left: COL_L, width: COL_W, bottom: 1920 - 1350, display: 'flex', justifyContent: 'center', fontFamily: FONT}}>
        <div style={{maxWidth: COL_W, boxSizing: 'border-box', padding: '16px 30px', borderRadius: 36, background: 'rgba(14,22,48,0.9)', fontSize: 48, lineHeight: 1.2, fontWeight: 800, textAlign: 'center', opacity: t}}>
          {TOKENS[s].slice(a, b + 1).map((tok, i) => {
            const wi = a + i;
            const started = f >= wordF(s, wi);
            const nextStart = wi + 1 < LINES[s].words.length ? wordF(s, wi + 1) : Infinity;
            const active = started && f < nextStart;
            return (
              <React.Fragment key={wi}>
                <span style={{color: active ? ORANGE : '#fff', opacity: started ? 1 : 0.6, whiteSpace: 'nowrap'}}>{tok}</span>
                {i < b - a ? ' ' : ''}
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </Layer>
  );
};

